#!/usr/bin/env node
// Builds js/app.bundle.js (the classic, file://-compatible runtime that index.html loads)
// from the readable sources: js/icons.js + js/app.js + js/entry-ui.js.
//
//   node tools/build-bundle.js            write js/app.bundle.js
//   node tools/build-bundle.js --check    exit 1 if js/app.bundle.js is out of date
//
// No dependencies. ES module syntax is stripped because the bundle must stay a classic script.
'use strict';
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const read = f => fs.readFileSync(path.join(root, f), 'utf8').replace(/\r\n/g, '\n');

function version() {
  const m = read('sw.js').match(/moze-v([\d.]+)-shell/);
  if (!m) throw new Error('cannot read version from sw.js CACHE name');
  return m[1];
}

function build() {
  const icons = read('js/icon-manifest.js') + '\n' + read('js/icons.js').replace(/^export\s+/gm, '');
  const app = read('js/app.js');
  const analysis = read('js/analysis.js');
  const budgets = read('js/budgets.js');
  const categories = read('js/categories.js');
  const categoryIcons = read('js/category-icons.js');
  const search = read('js/search.js');
  const projects = read('js/projects.js');
  const accounts = read('js/accounts.js');
  const reminders = read('js/reminders.js');
  const subscriptions = read('js/subscriptions.js');
  const yearly = read('js/yearly.js');
  const recon = read('js/recon-mode.js') + '\n' + read('js/tx-extra.js') + '\n' + read('js/tx-post.js') + '\n' + read('js/tx-fx.js') + '\n' + read('js/entry-plus.js') + '\n' + read('js/tx-attach.js') + '\n' + read('js/notify.js') + '\n' + read('js/changelog.js') + '\n' + read('js/card-plus.js') + '\n' + read('js/card-inst.js') + '\n' + read('js/rewards.js') + '\n' + read('js/reports.js') + '\n' + read('js/loan-plus.js') + '\n' + read('js/series.js') + '\n' + read('js/acct-plus.js') + '\n' + read('js/prefs-plus.js') + '\n' + read('js/split-plus.js') + '\n' + read('js/prefs-sync.js') + '\n' + read('js/inst-plus.js') + '\n' + read('js/entry-fields.js') + '\n' + read('js/entry-items.js') + '\n' + read('js/acct-view.js') + '\n' + read('js/loan-more.js') + '\n' + read('js/sys-plus.js') + '\n' + read('js/drafts.js') + '\n' + read('js/gestures.js') + '\n' + read('js/invoice.js') + '\n' + read('js/detail-card.js') + '\n' + read('js/report-view.js') + '\n' + read('js/ui-ask.js') + '\n' + read('js/adv-plus.js') + '\n' + read('js/card-view.js') + '\n' + read('js/event-view.js') + '\n' + read('js/find-view.js') + '\n' + read('js/doc-gaps.js') + '\n' + read('js/date-pick.js') + '\n' + read('js/adv-rows.js') + '\n' + read('js/invoice-csv.js') + '\n' + read('js/invoice-view.js') + '\n' + read('js/ov-order.js') + '\n' + read('js/einvoice-dl.js') + '\n' + read('js/inv-match.js');
  const settings = read('js/settings.js');
  const entryAssist = read('js/entry-assist.js');
  const installments = read('js/installments.js');
  const bulk = read('js/bulk.js');
  const backup = read('js/backup.js');
  const health = read('js/health.js');
  const lock = read('js/lock.js');
  const entryMoze = read('js/entry-moze.js');
  const entry = read('js/entry-ui.js').replace(/^\s*import\s+[^;]+;\s*$/gm, '');
  const out = [
    `/* 帳小簿 V${version()} low-memory bundle — file:// compatible runtime */`,
    `/* GENERATED by tools/build-bundle.js from js/icons.js + js/app.js + js/analysis.js + js/budgets.js + js/categories.js + js/category-icons.js + js/search.js + js/projects.js + js/accounts.js + js/reminders.js + js/subscriptions.js + js/yearly.js + js/recon-mode.js + js/settings.js + js/entry-assist.js + js/installments.js + js/bulk.js + js/backup.js + js/health.js + js/lock.js + js/entry-moze.js + js/entry-ui.js — do not edit by hand. */`,
    icons.trimEnd(),
    '',
    app.trimEnd(),
    '',
    analysis.trimEnd(),
    '',
    budgets.trimEnd(),
    '',
    categories.trimEnd(),
    '',
    categoryIcons.trimEnd(),
    '',
    search.trimEnd(),
    '',
    projects.trimEnd(),
    '',
    accounts.trimEnd(),
    '',
    reminders.trimEnd(),
    '',
    subscriptions.trimEnd(),
    '',
    yearly.trimEnd(),
    '',
    recon.trimEnd(),
    '',
    settings.trimEnd(),
    '',
    entryAssist.trimEnd(),
    '',
    installments.trimEnd(),
    '',
    bulk.trimEnd(),
    '',
    backup.trimEnd(),
    '',
    health.trimEnd(),
    '',
    lock.trimEnd(),
    '',
    entryMoze.trimEnd(),
    '',
    entry.trim(),
    '',
  ].join('\n');
  if (/^\s*(import|export)\s/m.test(out)) throw new Error('bundle still contains import/export');
  return out;
}

const target = path.join(root, 'js', 'app.bundle.js');
const next = build();
if (process.argv.includes('--check')) {
  const cur = fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n');
  if (cur !== next) { console.error('js/app.bundle.js is OUT OF DATE — run: node tools/build-bundle.js'); process.exit(1); }
  console.log('js/app.bundle.js is up to date');
} else {
  fs.writeFileSync(target, next);
  console.log(`wrote js/app.bundle.js (${next.length} chars)`);
}
